define(["core/notification"],function(Notification){const init=()=>{document.addEventListener("click",event=>{const link=event.target.closest('[data-action="delete"]');if(!link){return}event.preventDefault();Notification.confirm(M.util.get_string("confirmdelete","videobranch"),M.util.get_string("confirmdeletebody","videobranch"),M.util.get_string("delete","moodle"),M.util.get_string("cancel","moodle"),()=>{window.location.href=link.href})})};return{init:init}});